    if (params.senderAccount) {
        const keyword = params.senderAccount.trim();
        filter.$expr = {
            $regexMatch: {
                input: {
                    $ifNull: [
                        "$info.bankAccountNumber",
                        "$sender.bankAccount"
                    ]
                },
                regex: keyword,
                options: "i"
            }
        };
    }
    if (params.receiverAccount) {
        filter["receiver.credit"] = {
            $regex: params.receiverAccount.trim(),
            $options: "i"
        };
    }
    if (params.connector) {
        const connector = params.connector;
        filter.$expr = {
            $eq: [
                {
                    $ifNull: [
                        "$info.bankConnector",
                        "$info.connector"
                    ]
                },
                connector
            ]
        };
    }

